/**
 * ONE PLAIN-ENGLISH LINE AT THE TOP OF THE AI READ, for a reader who does not know the vocabulary.
 *
 * "Leaning bearish. Watch $73,400: a break below confirms it; a move back above $73,800 cancels it."
 *
 * **Built from fields the read already carries, never from a second AI call** - the owner's
 * instruction, 2026-11-10, and the only honest way to do it: a summary generated by asking the model
 * to summarise itself can disagree with the read printed underneath it, and the reader has no way to
 * tell which one is wrong.
 *
 * **NO INVENTED NUMBERS. A missing field drops its clause and nothing else.** So the line degrades
 * to "Leaning bearish." rather than inventing a level, and a read with no levels at all still gets
 * its verdict sentence.
 *
 * RETURNS LABEL KEYS, NOT ENGLISH. The component resolves them through `t()`, so this stays a pure
 * function a test can target and the copy stays translatable - the same split the rest of `lib/`
 * uses. It also means this file cannot accidentally become a second source of user-facing copy.
 */
import { priceText } from './numberFormat.ts';

/** A level as the read carries it. Matches `CombinedResult['levels'][number]`. */
export interface SummaryLevel {
  price: number;
  type: 'support' | 'resistance';
}

export type SummaryVerdictKey =
  | 'ARENA_PLAIN_SUMMARY_BULLISH'
  | 'ARENA_PLAIN_SUMMARY_LEAN_BULLISH'
  | 'ARENA_PLAIN_SUMMARY_FLAT'
  | 'ARENA_PLAIN_SUMMARY_LEAN_BEARISH'
  | 'ARENA_PLAIN_SUMMARY_BEARISH';

export interface PlainSummary {
  verdictKey: SummaryVerdictKey;
  /** The level whose break confirms the read. Absent when the read names none. */
  watch?: { key: 'ARENA_PLAIN_SUMMARY_WATCH_ABOVE' | 'ARENA_PLAIN_SUMMARY_WATCH_BELOW'; price: string };
  /** The level whose break cancels it. Absent when the read names none. */
  cancel?: { key: 'ARENA_PLAIN_SUMMARY_CANCEL_ABOVE' | 'ARENA_PLAIN_SUMMARY_CANCEL_BELOW'; price: string };
}

const VERDICT: Record<string, SummaryVerdictKey> = {
  'BULLISH': 'ARENA_PLAIN_SUMMARY_BULLISH',
  'LEAN BULLISH': 'ARENA_PLAIN_SUMMARY_LEAN_BULLISH',
  'FLAT': 'ARENA_PLAIN_SUMMARY_FLAT',
  'LEAN BEARISH': 'ARENA_PLAIN_SUMMARY_LEAN_BEARISH',
  'BEARISH': 'ARENA_PLAIN_SUMMARY_BEARISH',
};

export function plainSummary(signal: string, levels: readonly SummaryLevel[] = []): PlainSummary | null {
  const verdictKey = VERDICT[signal];
  if (!verdictKey) return null;           // an unknown tier gets no line rather than a guessed one

  /* `type` DECIDES WHICH SIDE A LEVEL IS ON, not a comparison against the current price. The read
     already classified each level as support or resistance, and re-deriving that from a price this
     function would have to be handed separately is how the line ends up contradicting the chart it
     sits above. Non-finite prices are dropped here so "nearest" cannot resolve to NaN. */
  const finite = levels.filter(l => Number.isFinite(l.price));
  const supports    = finite.filter(l => l.type === 'support').map(l => l.price);
  const resistances = finite.filter(l => l.type === 'resistance').map(l => l.price);

  /* Nearest to price WITHOUT needing the price: the highest support is the closest one below, and
     the lowest resistance the closest one above. */
  const nearestSupport    = supports.length    ? Math.max(...supports)    : null;
  const nearestResistance = resistances.length ? Math.min(...resistances) : null;

  const bullish = verdictKey === 'ARENA_PLAIN_SUMMARY_BULLISH' || verdictKey === 'ARENA_PLAIN_SUMMARY_LEAN_BULLISH';
  const bearish = verdictKey === 'ARENA_PLAIN_SUMMARY_BEARISH' || verdictKey === 'ARENA_PLAIN_SUMMARY_LEAN_BEARISH';

  /* FLAT GETS THE VERDICT SENTENCE ONLY, deliberately. With no direction there is no "a break this
     way confirms it" - the read's own `waitFor` field is what covers that case, and it is already
     rendered elsewhere. Saying "watch $X" without saying which way would be worse than silence. */
  if (!bullish && !bearish) return { verdictKey };

  const confirm = bullish ? nearestResistance : nearestSupport;
  const invalid = bullish ? nearestSupport    : nearestResistance;

  const out: PlainSummary = { verdictKey };
  if (confirm != null) {
    out.watch = {
      key: bullish ? 'ARENA_PLAIN_SUMMARY_WATCH_ABOVE' : 'ARENA_PLAIN_SUMMARY_WATCH_BELOW',
      price: priceText(confirm),
    };
  }
  if (invalid != null) {
    out.cancel = {
      key: bullish ? 'ARENA_PLAIN_SUMMARY_CANCEL_BELOW' : 'ARENA_PLAIN_SUMMARY_CANCEL_ABOVE',
      price: priceText(invalid),
    };
  }
  return out;
}
